@app.route("/deserialize", methods=["POST"])
def deserialize_data():
    try:
        import json
        import base64
        serialized_data = request.form.get("serialized_data", "")
        decoded_data = base64.b64decode(serialized_data)
        # Use JSON for safe deserialization of data-only formats
        data = json.loads(decoded_data)

        if isinstance(data, dict) and "username" in data and "is_admin" in data:
            username = data["username"]
            is_admin = data["is_admin"]
            if is_admin:
                message = f"Welcome Admin {username}! Here's the secret admin content: ADMIN_KEY_123"
            else:
                message = (
                    f"Welcome {username}. Only admins can see the secret content."
                )
        else:
            message = "Invalid user data"

        return render_template("result.html", message=message)
    except Exception as e:
        return render_template("result.html", message=f"Error: {str(e)}")
